(* [comment removed for export] *)
(* [comment removed for export] *)

Definition peof_body_flags (c : pcore) : bool := Z.testbit (pc_f c) 10 || Z.testbit (pc_f c) 11.

(* [comment removed for export] *)
Definition peof_assigns (c : pcore) : bool :=
  (pc_state c <=? 2) || (peof_body_flags c && negb (pc_state c =? 11)).

Definition peof_res (c : pcore) : ecv * pcore :=
  if pc_state c <=? 2 then (EC_http_loc HE_PARTIAL_MESSAGE LOC_PEOF_1, c)
  else if peof_body_flags c then
         (if pc_state c =? 11 then (EC_clear, c) else (EC_http_loc HE_PARTIAL_MESSAGE LOC_PEOF_2, c))
  else (EC_clear, pc_set_state c 11).

(* [comment removed for export] *)
Definition body_W (lo : Z) (sp : word) (P E : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp); (P, P + 80); (E, E + 24); (G_HTTP_CAT, G_HTTP_CAT + 64)]%Z.

Definition peof_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P E lo : Z) (c : pcore) (pad7 pad2 : list byte) (g : bool) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch (body_W lo sp P E) m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ rw_cells usegs m' P (ParserCoreCells (snd (peof_res c)) pad7 pad2)
    /\ rw_cells usegs m' E (ErrCodeCells (fst (peof_res c)))
